/**
 * 한 바퀴의 진행도(--rill-progress)가 from 에서 to 로 가는 동안 획 하나를 그린다. 구간 앞에서는 비어 있고
 * 뒤에서는 다 그려진 채로 남는다. pathLength 가 1000 이라 1000px 이 획 전체 길이다.
 */
function drawStroke(from: number, to: number): React.CSSProperties {
  return {
    strokeDashoffset: `calc(1000px * (1 - clamp(0, (var(--rill-progress) - ${from}) / (${to} - ${from}), 1)))`,
  };
}

